transforms.pre:
(
  $data:= $components.CreateForm.data;
  $id:= $components.CreateForm.data.code;

  {
    "payload": {

      "create": {
        "code": $id,
        "id": $id,
        "name": $data.name,
        "active": $data.active,
        "externalId": $data.externalId,
        "production": $data.type = "production" ? true : false,
        "distribution": $data.type = "distribution" ? true : false,
        "other": $data.type = "other" ? true : false,
        "customData": $data.customData,
        "integrationData": $data.integrationData
        
      }
    }
  }
)

(
  $data:= $components.Form5.data;
  $id:= $components.Form5.data.name;

  {
    "payload": 
    {
      "create": {
        "name": $data.name,
        "code": $data.code,
        "id": $id,
        "description": $data.description,
        "active": $data.active,
        "customData": $data.customData,
        "integrationData": $data.integrationData,
        "externalId": $data.externalId,
        "process": $data.type = "process" ? true : false,
        "productionCell": $data.type = "productionCell" ? true : false,
